command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="290ef0ce94b42a3b97efb3ea3452e6bbfd719955"
$candidate="e0e9483704a53ac4caddd20b06146bcdfe577044"
$branch="work/removable-metadata-sort-20261006"
$temp=Join-Path $env:RUNNER_TEMP ("fly-removable-metadata-"+$env:GITHUB_RUN_ID)
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "removable metadata fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before removable metadata acceptance"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "removable metadata candidate moved"}
if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp 2>$null;Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue}
& git worktree add --detach $temp $candidate
if($LASTEXITCODE -ne 0){throw "removable metadata worktree creation failed"}
try{
  Set-Location -LiteralPath $temp
  & git diff --check ($main+"..."+$candidate)
  if($LASTEXITCODE -ne 0){throw "removable metadata diff check failed"}
  & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
  if($LASTEXITCODE -ne 0){throw "removable metadata FAST failed"}
  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "removable metadata Release build failed"}
  $exe=Join-Path $temp "out\winui\Release\flyExplorer.exe"
  if(!(Test-Path -LiteralPath $exe -PathType Leaf)){throw "removable metadata executable missing"}
  & python -X utf8 tests\winui\test_metadata_sort_gui.py --configuration Release --exe $exe --owned-sort-mode 2 --capture after
  if($LASTEXITCODE -ne 0){throw "metadata size regression failed"}
  & python -X utf8 tests\winui\test_metadata_sort_gui.py --configuration Release --exe $exe --owned-sort-mode 3
  if($LASTEXITCODE -ne 0){throw "metadata date regression failed"}
  & python -X utf8 tests\winui\test_metadata_sort_gui.py --configuration Release --exe $exe --owned-sort-mode 4
  if($LASTEXITCODE -ne 0){throw "metadata type regression failed"}
  $removable=@(Get-CimInstance Win32_LogicalDisk | Where-Object {$_.DriveType -eq 2})
  if($removable.Count -eq 0){
    Write-Host "REMOVABLE_METADATA_PHYSICAL_USB=NOT_RUN_NO_DEVICE"
  }else{
    foreach($d in $removable){Write-Host ("REMOVABLE_METADATA_DEVICE={0} FS={1}" -f $d.DeviceID,$d.FileSystem)}
    Write-Host "REMOVABLE_METADATA_PHYSICAL_USB=DEVICE_PRESENT_NOT_MUTATED"
  }
  Write-Host "REMOVABLE_METADATA_FAST=PASS"
  Write-Host "REMOVABLE_METADATA_RELEASE=PASS"
  Write-Host "REMOVABLE_METADATA_SIZE=PASS"
  Write-Host "REMOVABLE_METADATA_DATE=PASS"
  Write-Host "REMOVABLE_METADATA_TYPE=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
